import{_ as i,o as a,c as s,ag as t}from"./chunks/framework.BGkQCay2.js";const k=JSON.parse('{"title":"Freestanding and No-Runtime Builds","description":"","frontmatter":{},"headers":[],"relativePath":"guide/freestanding.md","filePath":"guide/freestanding.md"}'),n={name:"guide/freestanding.md"};function r(l,e,h,d,o,p){return a(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="freestanding-and-no-runtime-builds" tabindex="-1">Freestanding and No-Runtime Builds <a class="header-anchor" href="#freestanding-and-no-runtime-builds" aria-label="Permalink to &quot;Freestanding and No-Runtime Builds&quot;">​</a></h1><p>Vex can compile without an implicit libc/CRT edge and can omit VexArch runtime memory-management and scheduling hooks. Freestanding mode is selected by <code>--no-runtime</code> or by <code>native.useSystemLibC: false</code> in the owning <code>vex.json</code>. It is not a source-level <code>no_std</code>, <code>no_main</code>, or global-allocator directive.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compile</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-runtime</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> x86_64-unknown-none</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kernel.vx</span></span></code></pre></div><p>Target and linker support still determine whether the final artifact is truly bare-metal. <code>--no-runtime</code> removes the normal Vex runtime edge; it does not magically supply an entry point, linker script, platform services, allocator, panic transport, or device I/O.</p><h2 id="what-changes" tabindex="-1">What changes <a class="header-anchor" href="#what-changes" aria-label="Permalink to &quot;What changes&quot;">​</a></h2><p>No-runtime mode:</p><ul><li>does not link the normal VexArch memory/scheduler runtime;</li><li>does not install the hosted <code>main</code> runtime setup path;</li><li>disables runtime ownership strategies that require shared reference counting;</li><li>makes runtime-only async/scheduler symbols unavailable;</li><li>requires every referenced platform/allocator symbol to be supplied by the program, target support layer, or link inputs.</li></ul><p>Language primitives, compile-time intrinsics, stack values, raw pointers, and inline assembly remain available. Standard-library modules that depend on OS or VexArch services are not freestanding merely because they type-check.</p><h2 id="entry-point" tabindex="-1">Entry point <a class="header-anchor" href="#entry-point" aria-label="Permalink to &quot;Entry point&quot;">​</a></h2><p>Export the symbol expected by the target ABI:</p><div class="language-vex vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vex</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">export </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;C&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> fn</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> _start</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> never {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // Initialize hardware and platform state.</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    loop</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The exact name and signature are target-specific. UEFI, an ELF kernel, a microcontroller image, and a hosted process do not share one universal entry contract.</p><h2 id="memory" tabindex="-1">Memory <a class="header-anchor" href="#memory" aria-label="Permalink to &quot;Memory&quot;">​</a></h2><p>Stack/static code needs no allocator:</p><div class="language-vex vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vex</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> buffer</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">u8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4096</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4096</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> counter</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> u32</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span></span></code></pre></div><p>Heap-using code must supply the allocation ABI required by the generated program. VexArch itself provides freestanding implementations of compiler- required memory routines when building the runtime artifacts; an independent no-runtime target must provide an equivalent target layer or avoid those paths.</p><p>Do not call host <code>malloc/free</code> merely to satisfy the linker. That turns a supposedly freestanding artifact back into a hosted libc-dependent program.</p><h2 id="panic-and-termination" tabindex="-1">Panic and termination <a class="header-anchor" href="#panic-and-termination" aria-label="Permalink to &quot;Panic and termination&quot;">​</a></h2><p>Code that can panic needs a target-appropriate termination/reporting path. A minimal bare target may halt:</p><div class="language-vex vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vex</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">fn</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> halt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> never {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    loop</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Production firmware or kernels usually provide architecture-specific panic logging before halting. Do not assume stderr, process exit, unwinding, or a filesystem exists.</p><p>In normal runtime builds, compiler-generated fail-fast paths call the VexArch <code>vex_sys_abort</code> ABI. VexArch selects the native target implementation (for example direct Linux system calls, Windows system services, or Apple&#39;s system ABI); the compiler does not inject a hidden libc <code>abort</code> dependency. A <code>--no-runtime</code> target that can reach such a path must provide <code>vex_sys_abort</code> itself or prove the path unreachable.</p><h2 id="hardware-access" tabindex="-1">Hardware access <a class="header-anchor" href="#hardware-access" aria-label="Permalink to &quot;Hardware access&quot;">​</a></h2><p>Memory-mapped I/O stays behind an unsafe boundary:</p><div class="language-vex vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vex</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">fn</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> writeUart</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(base</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> usize</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, byte</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> u8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> register </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> base </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">as</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Ptr</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">u8</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    unsafe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">register </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> byte }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Use <code>asm!</code> only when the target operation cannot be expressed through a volatile/MMIO abstraction. Inline-assembly operands use the dedicated syntax documented in <a href="/docs/guide/advanced/assembly">Assembly</a>.</p><h2 id="link-validation" tabindex="-1">Link validation <a class="header-anchor" href="#link-validation" aria-label="Permalink to &quot;Link validation&quot;">​</a></h2><p>Extern providers remain explicit:</p><table tabindex="0"><thead><tr><th>Provider</th><th>Freestanding behavior</th></tr></thead><tbody><tr><td><code>LIBC</code></td><td>A reachable call is rejected before linking</td></tr><tr><td><code>SYSTEM from &quot;library&quot;</code></td><td>Allowed when the target OS provides that ABI</td></tr><tr><td><code>NATIVE from &quot;feature&quot;</code></td><td>Allowed when the selected artifact is freestanding-compatible</td></tr><tr><td><code>VEX</code></td><td>Available only through the selected compiler/runtime configuration</td></tr></tbody></table><p>Freestanding does not mean “no system dylib or DLL.” An OS may define its stable ABI through <code>libSystem</code>, <code>kernel32</code>, or another system library without making the program libc-hosted. The forbidden behavior is a hidden, unavoidable libc/CRT dependency.</p><p>WASM rejects dynamic native artifacts. Other targets may use dynamic <code>SYSTEM</code> or <code>NATIVE</code> providers when the target supports them. Native-link diagnostics identify known libc and TLS dependencies from the exact activated static feature; unused manifest entries cannot affect the result. Treat these as architecture errors to remove, not symbols to paper over with compatibility stubs.</p><p>When using clang, freestanding linking passes <code>-nostdlib</code>. The Linux direct-LLD path likewise omits automatic CRT objects, dynamic-loader selection, libc, libm, and libgcc inputs. The program must supply its own entry and required target support.</p><h2 id="verification-checklist" tabindex="-1">Verification checklist <a class="header-anchor" href="#verification-checklist" aria-label="Permalink to &quot;Verification checklist&quot;">​</a></h2><ol><li>Compile with <code>--no-runtime</code> for the exact target triple.</li><li>Provide the correct entry symbol and linker script/format.</li><li>Inspect undefined symbols; no accidental libc, TLS, or Vex scheduler edge should remain.</li><li>Verify compiler-required memory operations are supplied by freestanding code.</li><li>Test the produced artifact on the real target or an accurate emulator.</li><li>Keep target-specific services beneath portable Vex ownership and container APIs.</li></ol><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/guide/advanced/assembly">Assembly</a></li><li><a href="/docs/guide/ffi-deep-dive">FFI Deep Dive</a></li><li><a href="/docs/guide/memory/mem-prelude">Memory Prelude</a></li><li><a href="/docs/guide/platform-support">Platform Support</a></li><li><a href="/docs/guide/advanced/unsafe">Unsafe</a></li></ul>`,36)])])}const g=i(n,[["render",r]]);export{k as __pageData,g as default};
